/// Published firmware metadata served at /fw/version.json next to main.bin.
/// Generated by deploy/fw.ps1 at deploy time from include/config.h.
class FirmwareManifest {
  final String version;
  final String deviceType;
  final DateTime? buildDate;
  final String? sha256;
  final String file;

  const FirmwareManifest({
    required this.version,
    required this.deviceType,
    this.buildDate,
    this.sha256,
    this.file = 'main.bin',
  });

  factory FirmwareManifest.fromJson(Map<String, dynamic> json) {
    final rawDate = json['build_date'];
    return FirmwareManifest(
      version: (json['version'] as String?)?.trim() ?? '',
      deviceType: (json['device_type'] as String?)?.trim() ?? 'esp32-c3',
      buildDate: rawDate is String ? DateTime.tryParse(rawDate) : null,
      sha256: (json['sha256'] as String?)?.trim(),
      file: (json['file'] as String?)?.trim() ?? 'main.bin',
    );
  }

  static FirmwareManifest? tryParse(dynamic data) {
    if (data is Map<String, dynamic>) return FirmwareManifest.fromJson(data);
    if (data is Map) {
      return FirmwareManifest.fromJson(
        data.map((k, v) => MapEntry(k.toString(), v)),
      );
    }
    return null;
  }

  String get buildDateLabel {
    final d = buildDate;
    if (d == null) return '—';
    final local = d.toLocal();
    return '${local.day.toString().padLeft(2, '0')}.'
        '${local.month.toString().padLeft(2, '0')}.'
        '${local.year} ${local.hour.toString().padLeft(2, '0')}:'
        '${local.minute.toString().padLeft(2, '0')}';
  }
}